UPDATE crm_youzan_customer_sync_run
SET status = 'FAILED',
    error_masked = '同步任务租约已超时，已自动释放并发锁',
    finished_at = #{now}
WHERE tenant_id = #{tenantId}
  AND shop_id = #{shopId}
  AND source_mode = #{sourceMode}
  AND status = 'RUNNING'
  AND lease_until IS NOT NULL
  AND lease_until < #{now}

